def _patch_break_glass_cidrs(raw: str):
    patched = replace(settings, break_glass_allowed_cidrs=raw)
    return patch("app.breakglass.settings", patched)


class TestSpecRequirements(unittest.TestCase):
    """Spec requirements — one focused check per REQ where automatable."""

    def test_req_001_version_id_required_and_pinned_in_source(self) -> None:
        """[Req: REQ-001] Exact VersionId required; crypt and plain pins present."""
        self.assertIn(
            'raise RuntimeError("Exact S3 VersionId is required for recovery")',
            STORAGE_PY,
        )
        self.assertIn("--s3-version-id=", STORAGE_PY)
        self.assertIn("VersionId=provider_version_id", STORAGE_PY)
        # Docstring may wrap across lines; match the lead phrase.
        self.assertIn("Path-only current-object downloads are", STORAGE_PY)
        self.assertIn("forbidden because they can return a different object version", STORAGE_PY)

    def test_req_002_recover_branch_lacks_status_conjunct(self) -> None:
        """[Req: REQ-002] Recover branch currently has no status whitelist (known gap)."""
        # Document current code shape for Phase 3: peers have status checks; recover does not.
        self.assertIn(
            'elif job["action"] == "recover":',
            STORAGE_PY,
        )
        self.assertIn(
            'elif job["action"] == "free-space" and job["status"] == "queued":',
            STORAGE_PY,
        )
        # Mechanical expectation for the requirement (desired): status set should appear.
        # This asserts the peer pattern exists so the gap is measurable.
        self.assertIn(
            'job["action"] == "upload" and job["status"] in {"queued", "retrying"}',
            STORAGE_PY,
        )

    def test_req_003_operator_not_owner_and_readme_conflict(self) -> None:
        """[Req: REQ-003] Operators are not owners; README Users over-claims free-space."""
        self.assertFalse(vault_roles.is_owner("operator"))
        self.assertTrue(vault_roles.is_owner("owner"))
        self.assertIn("free local space", README.lower())
        # Users section claims operators can free local space (conflict).
        self.assertRegex(
            README,
            r"operator` can upload, free\s+local space, and recover",
        )
        # Local cleanup safety correctly restricts to owners.
        self.assertIn("for owners", README)

    def test_req_006_break_glass_fail_closed_and_loopback(self) -> None:
        """[Req: REQ-006] Missing IP denied; loopback allowed with empty CIDRs."""
        with _patch_break_glass_cidrs(""):
            self.assertFalse(breakglass.is_break_glass_allowed(None))
            self.assertFalse(breakglass.is_break_glass_allowed("not-an-ip"))
            self.assertTrue(breakglass.is_break_glass_allowed("127.0.0.1"))
            self.assertFalse(breakglass.is_break_glass_allowed("203.0.113.5"))

    def test_req_007_untrusted_peer_ignores_forwarded_for(self) -> None:
        """[Req: REQ-007] XFF ignored when peer is not a Trusted Proxy."""
        trusted = [ipaddress.ip_network("10.0.0.0/8")]
        resolved = resolve_client_ip(
            peer="203.0.113.9",
            forwarded_for="10.0.0.5",
            trusted_proxies=trusted,
        )
        self.assertEqual(resolved, "203.0.113.9")

    def test_req_007_trusted_peer_uses_rightmost_untrusted_hop(self) -> None:
        """[Req: REQ-007] Trusted peer + XFF selects client hop."""
        trusted = [ipaddress.ip_network("10.0.0.0/8")]
        resolved = resolve_client_ip(
            peer="10.0.0.1",
            forwarded_for="203.0.113.50, 10.0.0.2",
            trusted_proxies=trusted,
        )
        self.assertEqual(resolved, "203.0.113.50")

    def test_req_010_head_schema_constant(self) -> None:
        """[Req: REQ-010] HEAD_SCHEMA_REVISION matches expected migration id."""
        self.assertEqual(HEAD_SCHEMA_REVISION, "0021_local_retention")
        self.assertTrue(issubclass(DatabaseSchemaError, RuntimeError))

    def test_req_011_custody_message_has_no_secret_material(self) -> None:
        """[Req: REQ-011] RecoveryCustodyRequired message does not embed secrets."""
        vault = {
            "id": 1,
            "encryption_mode": "crypt",
            "recovery_custody_confirmed_at": None,
        }
        # Force the helper path via public API when custody required.
        if hasattr(vault_recovery, "vault_requires_recovery_custody"):
            with patch(
                "app.services.vault_recovery.vault_requires_recovery_custody",
                return_value=True,
            ):
                with self.assertRaises(RecoveryCustodyRequired) as ctx:
                    vault_recovery.require_upload_custody(vault)
                message = str(ctx.exception).lower()
                self.assertNotIn("password", message)
                self.assertNotIn("secret=", message)
                self.assertIn("custody", message)

    def test_req_012_operating_window_start_before_end(self) -> None:
        """[Req: REQ-012] Overnight / inverted windows rejected."""
        with self.assertRaises(ValueError):
            operation_policies._normalize_windows(
                [{"weekday": 1, "start": "22:00", "end": "06:00"}]
            )
        with self.assertRaises(ValueError):
            operation_policies._normalize_windows(
                [{"weekday": 1, "start": "09:00", "end": "09:00"}]
            )
        ok = operation_policies._normalize_windows(
            [{"weekday": 1, "start": "09:00", "end": "17:00"}]
        )
        self.assertEqual(ok[0]["start"], "09:00")

    def test_req_016_can_operate_matrix(self) -> None:
        """[Req: REQ-016] Owner and operator can operate; viewer cannot."""
        self.assertTrue(vault_roles.can_operate("owner"))
        self.assertTrue(vault_roles.can_operate("operator"))
        self.assertFalse(vault_roles.can_operate("viewer"))

    def test_req_017_viewer_not_owner(self) -> None:
        """[Req: REQ-017] Viewer is read-only at role helpers."""
        self.assertFalse(vault_roles.is_owner("viewer"))
        self.assertFalse(vault_roles.can_operate("viewer"))
        self.assertTrue(vault_roles.is_valid_role("viewer"))


