class TestBoundaries(unittest.TestCase):
    """Boundaries and defensive patterns."""

    def test_break_glass_empty_string_ip_denied(self) -> None:
        with _patch_break_glass_cidrs("10.0.0.0/8"):
            self.assertFalse(breakglass.is_break_glass_allowed(""))

    def test_resolve_client_ip_missing_peer(self) -> None:
        self.assertIsNone(
            resolve_client_ip(peer=None, forwarded_for="1.2.3.4", trusted_proxies=[])
        )

    def test_resolve_client_ip_all_hops_trusted_returns_first(self) -> None:
        trusted = [ipaddress.ip_network("10.0.0.0/8")]
        resolved = resolve_client_ip(
            peer="10.0.0.9",
            forwarded_for="10.0.0.1, 10.0.0.2",
            trusted_proxies=trusted,
        )
        self.assertEqual(resolved, "10.0.0.1")

    def test_operating_window_rejects_bad_weekday(self) -> None:
        with self.assertRaises(ValueError):
            operation_policies._normalize_windows(
                [{"weekday": 7, "start": "09:00", "end": "10:00"}]
            )

    def test_valid_roles_closed_set(self) -> None:
        for role in ("owner", "operator", "viewer"):
            self.assertTrue(vault_roles.is_valid_role(role))
        self.assertFalse(vault_roles.is_valid_role("admin"))

    def test_download_helper_signature_requires_version_id(self) -> None:
        from app import storage

        sig = inspect.signature(storage.download_exact_version_plaintext)
        self.assertIn("provider_version_id", sig.parameters)

    def test_cloud_archive_source_records_marker_version(self) -> None:
        start = STORAGE_PY.index("def process_cloud_archive")
        end = STORAGE_PY.index("\ndef process_cloud_purge", start)
        body = STORAGE_PY[start:end]
        self.assertIn("marker_version", body)
        self.assertIn("record_delete_marker", body)

    def test_process_job_cancelled_short_circuit_in_source(self) -> None:
        start = STORAGE_PY.index("def process_job")
        end = STORAGE_PY.index("\ndef process_jobs_once", start)
        self.assertIn('current["status"] == "cancelled"', STORAGE_PY[start:end])


